import json
import os

# Read all polymorph files
polymorph_dir = '../CORRAL_WORK_DIR/ml_ujqraq/ml_nitrides_trial_14/polymorph_data'
polymorph_files = glob.glob(os.path.join(polymorph_dir, '*_polymorphs.json'))

filtered_data = []

for file_path in polymorph_files:
    try:
        with open(file_path, 'r') as f:
            file_data = json.load(f)
            composition = os.path.basename(file_path).replace('_polymorphs.json', '')
            for polymorph in file_data:
                polymorph['source_composition'] = composition
                filtered_data.append(polymorph)
    except Exception as e:
        print(f'Error loading {file_path}: {e}')

print(f'Consolidated {len(filtered_data)} polymorphs from {len(polymorph_files)} files')"}, 'result': '{
